products AS (
  INSERT INTO public.products
    (name, slug, description, brand_id, category_id, mrp_paise, price_paise, unit_label,
     stock, low_stock_threshold, images, tags, rating, is_active)
  SELECT d.name, d.slug, '', b.id, c.id, d.mrp_paise, d.price_paise,
    d.unit_label, d.stock, 10, d.images, d.tags, 0, true
  FROM product_data d
  CROSS JOIN brand b
  JOIN public.categories c ON c.slug=d.target_category_slug AND c.parent_id IS NULL
  ON CONFLICT (slug) DO NOTHING
  RETURNING id, slug
)
SELECT
  (SELECT count(*) FROM products) AS products_inserted,
  (SELECT count(*) FROM category_map m JOIN public.categories c ON c.slug=m.target_category_slug AND c.parent_id IS NULL) AS existing_parent_categories_used,
  (SELECT count(*) FROM brand) AS brand_handled;
